import { useEffect, useRef, useState } from "react";
import { chatWithProviderConfiguration } from "../../services/llmProviderService";

// Test chat for one saved configuration: the reply is generated by the provider with that configuration's credential,
// model, settings and parameters. The conversation lives in the parent so it survives switching tabs.

const SendIcon = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="19" x2="12" y2="5" /><polyline points="5 12 12 5 19 12" /></svg>
);

const SUGGESTIONS = ["Say hello and tell me which model you are.", "Explain what an API key is in two sentences.", "Write a short haiku about the sea."];

export default function ProviderChat({ provider, configuration, dirty, messages, setMessages, isLight }) {
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const scrollRef = useRef(null);

  const muted = isLight ? "text-gray-500" : "text-[#8B98A8]";
  const line = isLight ? "border-[#E5E4E7]" : "border-[#263241]/60";

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, sending]);

  const ready = Boolean(configuration);
  const missing = ready && (!configuration.model ? "Choose a model in this configuration first." : null);

  const send = async () => {
    const text = input.trim();
    if (!text || sending || !ready || missing) return;
    const next = [...messages, { role: "user", content: text }];
    setMessages(next);
    setInput("");
    setError("");
    setSending(true);
    try {
      // only roles and text go up; usage and error notes are display-only
      const history = next.filter((m) => m.role === "user" || m.role === "assistant").map(({ role, content }) => ({ role, content }));
      const reply = await chatWithProviderConfiguration(provider.id, configuration.id, history);
      setMessages([...next, { role: "assistant", content: reply.content, usage: reply.usage }]);
    } catch (err) {
      setError(err.message || "The provider could not generate a response.");
    } finally {
      setSending(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  };

  if (!ready) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 px-8 text-center">
        <p className="m-0 text-[14px] font-semibold">No configuration to test</p>
        <p className={`m-0 text-[13px] leading-snug ${muted}`}>Save a configuration on the Configuration tab, then come back here to chat with it.</p>
      </div>
    );
  }

  const tokens = (usage) => (usage?.total_tokens ? `${usage.total_tokens} tokens` : null);

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className={`shrink-0 border-b px-5 py-3 ${line}`}>
        <div className="flex items-center justify-between gap-3">
          <span className="min-w-0">
            <span className="block truncate text-[13.5px] font-semibold">{configuration.name}</span>
            <span className={`block truncate text-[11.5px] ${muted}`}>{configuration.model || "no model selected"}</span>
          </span>
          {messages.length > 0 && (
            <button type="button" onClick={() => { setMessages([]); setError(""); }} className="shrink-0 cursor-pointer border-0 bg-transparent p-0 text-[12px] font-medium text-(--accent-readable) hover:underline">
              Clear chat
            </button>
          )}
        </div>
        {dirty && <p className="m-0 mt-2 text-[12px] text-amber-500">You have unsaved changes. The chat uses the saved version.</p>}
        {missing && <p className="m-0 mt-2 text-[12px] text-rose-500">{missing}</p>}
      </div>

      <div ref={scrollRef} className="scrollable flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-5 py-4">
        {messages.length === 0 && !sending && (
          <div className="mt-6 flex flex-col items-center gap-4 text-center">
            <p className="m-0 text-[14px] font-semibold">Try this configuration</p>
            <p className={`m-0 text-[13px] leading-snug ${muted}`}>Ask anything. The reply comes from {provider.name} using the saved key, model and settings.</p>
            <div className="flex flex-col gap-2 self-stretch">
              {SUGGESTIONS.map((text) => (
                <button
                  key={text}
                  type="button"
                  disabled={Boolean(missing)}
                  onClick={() => setInput(text)}
                  className={`cursor-pointer border px-3 py-2 text-left text-[13px] transition-colors hover:border-(--accent-color) disabled:cursor-not-allowed disabled:opacity-50 ${line} ${isLight ? "text-gray-700" : "text-[#B8C4D0]"}`}
                >
                  {text}
                </button>
              ))}
            </div>
          </div>
        )}
        {messages.map((m, i) =>
          m.role === "user" ? (
            <div key={i} className="flex flex-col items-end gap-1">
              <span className={`text-[11px] font-medium ${muted}`}>You</span>
              <div className="max-w-[88%] whitespace-pre-wrap px-3 py-2.5 text-[13.5px] leading-relaxed text-black" style={{ background: "var(--accent-paint)" }}>{m.content}</div>
            </div>
          ) : (
            <div key={i} className="flex flex-col items-start gap-1">
              <span className="text-[11px] font-medium text-(--accent-readable)">{provider.name}</span>
              <div className={`max-w-[92%] whitespace-pre-wrap border px-3 py-2.5 text-[13.5px] leading-relaxed ${line} ${isLight ? "bg-white text-gray-900" : "bg-gray-950 text-[#D6DEE8]"}`}>{m.content}</div>
              {tokens(m.usage) && <span className={`text-[11px] ${muted}`}>{tokens(m.usage)}</span>}
            </div>
          )
        )}
        {sending && (
          <div className="flex flex-col items-start gap-1">
            <span className="text-[11px] font-medium text-(--accent-readable)">{provider.name}</span>
            <div className={`flex items-center gap-1 border px-3.5 py-3 ${line} ${isLight ? "bg-white" : "bg-gray-950"}`}>
              {[0, 150, 300].map((delay) => (
                <span key={delay} className="h-1.5 w-1.5 animate-bounce rounded-full bg-(--accent-readable)" style={{ animationDelay: `${delay}ms` }} />
              ))}
            </div>
          </div>
        )}
        {error && <p className="m-0 border border-rose-500/40 px-3 py-2.5 text-[12.5px] leading-snug text-rose-500">{error}</p>}
      </div>

      <div className={`shrink-0 border-t px-5 py-3 ${line}`}>
        <div className={`flex items-end gap-2 border px-3 py-2 transition-colors focus-within:border-(--accent-color) ${line} ${isLight ? "bg-white" : "bg-black"}`}>
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={onKeyDown}
            rows={1}
            placeholder={missing ? "Fix the configuration to chat" : "Type a message…"}
            disabled={Boolean(missing)}
            aria-label="Message"
            className={`max-h-32 min-h-6 flex-1 resize-none border-0 bg-transparent py-0.5 text-[13.5px] outline-none ${isLight ? "placeholder:text-gray-400" : "placeholder:text-[#566273]"}`}
          />
          <button
            type="button"
            onClick={send}
            disabled={!input.trim() || sending || Boolean(missing)}
            aria-label="Send message"
            className="flex h-8 w-8 shrink-0 cursor-pointer items-center justify-center border-0 text-black transition-opacity disabled:cursor-not-allowed disabled:opacity-40"
            style={{ background: "var(--accent-paint)" }}
          >
            <SendIcon />
          </button>
        </div>
        <p className={`m-0 mt-1.5 text-[11.5px] ${muted}`}>Enter to send · Shift+Enter for a new line</p>
      </div>
    </div>
  );
}
